97		base := flags.Base
98		if base == "" {
99			base, err = gitutil.MergeBase(ctx, repo, flags.Refs[0], flags.Refs[1])
100			if err != nil {
101				return fmt.Errorf("merge-radar: no merge base between %s and %s; pass --base <ref>: %w", flags.Refs[0], flags.Refs[1], err)
102			}
103		}
104		report, err := sem.AnalyzeMerge(ctx, repo, base, flags.Refs[0], flags.Refs[1], flags.Depth)
105		if err != nil {
106			return err
107		}
108		if !flags.NoIntent {
109			if err := sem.AttachIntent(ctx, repo, &report); err != nil {
110				return err
111			}
112		}
113		if flags.JSON {
114			encoder := json.NewEncoder(termsafe.NewJSONWriter(opts.Stdout))
115			encoder.SetEscapeHTML(false)
116			encoder.SetIndent("", "  ")
117			return encoder.Encode(report)
118		}
119		writeMergeRadarText(opts.Stdout, report, flags.Depth)
120		return nil
121	}
