130	func writeMergeRadarText(out io.Writer, report sem.MergeReport, depth int) {
131		hoisted := hoistedIntents(report)
132		fmt.Fprintf(out, "MergeRadar  base %s  depth %d\n", shortSHA(report.Base), depth)
133		writeMergeSide(out, "A", report.A, hoisted[report.A.Ref])
134		writeMergeSide(out, "B", report.B, hoisted[report.B.Ref])
135		fmt.Fprintln(out)
136	
137		if len(report.Conflicts) == 0 {
138			fmt.Fprintln(out, "No cross-branch conflicts found at this depth.")
139			fmt.Fprintln(out, "The graph saw no entity changed on one branch that changed or added code on the other references.")
140			fmt.Fprintln(out, "This is not proof the merge is safe: relationships through configuration, serialised data or runtime strings are invisible to the graph.")
141		} else {
142			fmt.Fprintf(out, "%d potential conflict(s). Labelled potential until a merged tree is actually tested.\n\n", len(report.Conflicts))
143			for i, c := range report.Conflicts {
144				writeMergeConflict(out, i+1, c, hoisted)
145			}
146		}
147	
148		fmt.Fprintln(out, "Verify before trusting this report:")
149		fmt.Fprintf(out, "  git merge-tree --write-tree %s %s    # scratch merge, no checkout\n", report.A.Ref, report.B.Ref)
150		fmt.Fprintln(out, "  then run the tests that touch the files listed above against that tree.")
151	
152		if len(report.Warnings) > 0 {
153			fmt.Fprintf(out, "\n%d analysis warning(s):\n", len(report.Warnings))
154			for _, w := range report.Warnings {
155				file := ""
156				if w.FilePath != "" {
157					file = " " + w.FilePath
158				}
159				fmt.Fprintf(out, "  %s%s: %s\n", w.Code, file, w.EffectOnCompleteness)
160			}
161		}
162	}
