164	func writeMergeSide(out io.Writer, letter string, side sem.MergeSide, intent *sem.CheckpointIntent) {
165		fmt.Fprintf(out, "  %s  %-24s %s  %d files, %d entities changed\n", letter, side.Ref, shortSHA(side.Commit), side.Files, side.Entities)
166		if intent != nil {
167			writeIntentLine(out, "     ", "intent", intent)
168		}
