171	// hoistedIntents returns, per branch ref, the single checkpoint intent that
172	// every conflict on that side quotes, so the text report states it once under
173	// the branch instead of repeating it under each finding. A side whose conflicts
174	// quote different checkpoints, or none, gets no entry and keeps its per-conflict
175	// lines. With no conflicts at all, each side's most recent intent is shown so
176	// the reader still sees what the two branches set out to do.
177	func hoistedIntents(report sem.MergeReport) map[string]*sem.CheckpointIntent {
178		hoisted := map[string]*sem.CheckpointIntent{}
179		if len(report.Conflicts) == 0 {
180			for _, side := range []*sem.MergeSide{&report.A, &report.B} {
181				if len(side.Intents) > 0 {
182					hoisted[side.Ref] = &side.Intents[0]
183				}
184			}
185			return hoisted
186		}
187		mixed := map[string]bool{}
188		consider := func(ref string, intent *sem.CheckpointIntent) {
189			if mixed[ref] {
190				return
191			}
192			prev, seen := hoisted[ref]
193			switch {
194			case intent == nil:
195				mixed[ref] = true
196				delete(hoisted, ref)
197			case !seen:
198				hoisted[ref] = intent
199			case prev.CheckpointID != intent.CheckpointID || prev.Commit != intent.Commit:
200				mixed[ref] = true
201				delete(hoisted, ref)
202			}
203		}
204		for _, c := range report.Conflicts {
205			consider(c.ChangedOn, c.ChangedIntent)
206			if c.Consumer != nil {
207				consider(c.ConsumerOn, c.ConsumerIntent)
208			}
209		}
210		return hoisted
211	}
