213	func writeMergeConflict(out io.Writer, n int, c sem.MergeConflict, hoisted map[string]*sem.CheckpointIntent) {
214		fmt.Fprintf(out, "[%d] %s  %s\n", n, strings.ToUpper(c.Kind), c.Confidence)
215		fmt.Fprintf(out, "    changed on %-12s %s %s  %s:%d  %s\n", c.ChangedOn, c.Changed.Kind, c.Changed.Name, c.Changed.Path, c.Changed.Line, c.Changed.Type)
216		if c.Changed.OldSignature != "" && c.Changed.NewSignature != "" && c.Changed.OldSignature != c.Changed.NewSignature {
217			fmt.Fprintf(out, "      - %s\n      + %s\n", c.Changed.OldSignature, c.Changed.NewSignature)
218		}
219		if c.Consumer != nil {
220			via := ""
221			if len(c.Via) > 0 {
222				names := make([]string, 0, len(c.Via))
223				for _, v := range c.Via {
224					names = append(names, v.Name)
225				}
226				via = "  via " + strings.Join(names, " -> ")
227			}
228			label := "consumer on"
229			if c.Kind == sem.ConflictDirect {
230				label = "also changed on"
231			}
232			fmt.Fprintf(out, "    %-11s %-12s %s %s  %s:%d  %s%s\n", label, c.ConsumerOn, c.Consumer.Kind, c.Consumer.Name, c.Consumer.Path, c.Consumer.Line, c.Consumer.Type, via)
233		}
234		if hoisted[c.ChangedOn] == nil {
235			writeIntentLine(out, "    ", "why "+c.ChangedOn, c.ChangedIntent)
236		}
237		if c.Consumer != nil && hoisted[c.ConsumerOn] == nil {
238			writeIntentLine(out, "    ", "why "+c.ConsumerOn, c.ConsumerIntent)
239		}
240		fmt.Fprintf(out, "    => %s\n\n", c.Explanation)
241	}
242	
243	// intentWrapWidth keeps quoted intents readable in a terminal; the JSON output
244	// carries them unwrapped.
245	const intentWrapWidth = 88
246	
247	func writeIntentLine(out io.Writer, indent, label string, intent *sem.CheckpointIntent) {
248		w := max(len(label), 6)
249		if intent == nil {
250			fmt.Fprintf(out, "%s%-*s (no commits on this side carry checkpoints)\n", indent, w, label)
251			return
252		}
253		if intent.Source == sem.IntentSourceMissing {
254			note := intent.Note
255			if note == "" {
256				note = "no recorded intent"
257			}
258			fmt.Fprintf(out, "%s%-*s [no intent: %s]  commit %s\n", indent, w, label, note, shortSHA(intent.Commit))
259			return
260		}
261		lines := wrapWords(intent.Intent, intentWrapWidth)
262		fmt.Fprintf(out, "%s%-*s \"%s", indent, w, label, lines[0])
263		for _, l := range lines[1:] {
264			fmt.Fprintf(out, "\n%s%-*s  %s", indent, w, "", l)
265		}
266		fmt.Fprintln(out, "\"")
267		evidence := []string{"checkpoint " + intent.CheckpointID, "commit " + shortSHA(intent.Commit), "from " + intent.Source}
268		if intent.Agent != "" {
269			evidence = append(evidence, intent.Agent)
270		}
271		if intent.Match != "" {
272			evidence = append(evidence, "matched by "+intent.Match)
273		}
274		fmt.Fprintf(out, "%s%-*s %s\n", indent, w, "", strings.Join(evidence, " · "))
275		if intent.Note != "" {
276			fmt.Fprintf(out, "%s%-*s note: %s\n", indent, w, "", intent.Note)
277		}
278	}
279	
280	// wrapWords splits s into lines of at most width runes at word boundaries. A
281	// single word longer than width stays on its own line. It always returns at
282	// least one line so callers can print lines[0] unconditionally.
283	func wrapWords(s string, width int) []string {
284		words := strings.Fields(s)
285		if len(words) == 0 {
286			return []string{s}
287		}
288		var lines []string
289		cur := words[0]
290		for _, word := range words[1:] {
291			if len([]rune(cur))+1+len([]rune(word)) > width {
292				lines = append(lines, cur)
293				cur = word
294				continue
295			}
296			cur += " " + word
297		}
298		return append(lines, cur)
299	}
